const item = $input.first();
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = item.json.headers || {};
return [{json:{base:`${h['webhook-id']}.${h['webhook-timestamp']}.${raw}`, sig:h['webhook-signature'] || '', ts:Number(h['webhook-timestamp']), raw}}];

const j = $input.first().json;
const cfg = $('Payment settings').first().json.config;
const same = (a,b) => { a=String(a); b=String(b); if(a.length!==b.length) return false; let v=0; for(let i=0;i<a.length;i++) v |= a.charCodeAt(i)^b.charCodeAt(i); return v===0; };
const sigs = String(j.sig).split(/\s+/).filter(s=>s.startsWith('v1,')).map(s=>s.slice(3));
if (!Number.isFinite(j.ts) || Math.abs(Date.now()/1000-j.ts)>300 || !sigs.some(s=>same(s,j.expected))) return [{json:{genuine:false,why:'Invalid signature or timestamp'}}];
const e = JSON.parse(j.raw), p = e.data || {}, m = p.metadata || {};
if ((e.account_id || e.company_id) !== cfg.whopAccountId) return [{json:{genuine:false,why:'Wrong Whop account'}}];
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || [];
const key = e.type + ':' + p.id;
const duplicate = !!p.id && sd.seen.includes(key);
const esc = v => String(v ?? '').slice(0,500).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const money = n => '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const rawPaid = p.usd_total ?? (p.currency === 'usd' ? p.total : null);
const paid = rawPaid == null ? NaN : Number(rawPaid);
const asked = Number(String(m.total || '').replace(/[$,]/g,''));
const paidText = Number.isFinite(paid) ? money(paid) : 'unknown USD amount';
const amountMatches = Number.isFinite(paid) && Number.isFinite(asked) && asked > 0 && Math.abs(paid-asked)<0.01;
const isProposal = e.type === 'payment.succeeded' && m.source === cfg.source && !!m.ghl_contact_id && !!p.id;
const isDeposit = e.type === 'deposit.succeeded' && p.line_type === 'topup' && !!p.id;
const act = !duplicate && isProposal && amountMatches;
const wire = !duplicate && (isDeposit || (e.type === 'payment.succeeded' && !!p.id && !act));
const u = p.user || {};
const matchText = isDeposit
 ? ':bank: Whop bank deposit '+(p.usd_amount == null ? '(amount unavailable)' : esc(money(Number(p.usd_amount))))+'. Deposit '+esc(p.id)+'. Match the sender and proposal manually before updating GHL.'
 : ':mag: Whop payment '+esc(p.id)+': '+paidText+'. Payer: '+[esc(u.name),esc(u.email)].filter(Boolean).join(', ')+'. '+(isProposal && !amountMatches ? 'Proposal amount could not be matched ('+esc(m.total)+').' : 'No matching proposal metadata.')+' Review before marking a proposal paid.';
return [{json:{...m, genuine:true, act, wire, duplicate, dedupeKey:key, type:e.type, paymentId:p.id,
 variantId:p.variant_id || p.variant?.id || p.plan?.id || '', paidText, how:' by '+esc(p.payment_method_type || m.pay_method || 'unknown method'),
 firm:esc(m.firm || 'a client'),rep:esc(m.rep),email:esc(m.email),leads:esc(m.leads),cpl:esc(m.cpl),state:esc(m.state),warn:'',matchText}}];

const c=$input.first().json.contact || {};
const cfg=$('Payment settings').first().json.config;
const raw=(c.customFields || []).find(f=>f.id===cfg.fields.planIds)?.value || '';
const ids=String(raw).split(',').map(s=>s.trim()).filter(s=>/^plan_[A-Za-z0-9]+$/.test(s));
const paid=$('Check').first().json.variantId;
return [{json:{current:ids.includes(paid), ids}}];

